{
  "name": "module-resolver",
  "version": "0.1.0",
  "description": "Programmatic Node.js module resolution (require.resolve semantics) for build tools",
  "type": "module",
  "main": "./src/index.js",
  "exports": {
    ".": "./src/index.js"
  },
  "files": [
    "src"
  ],
  "engines": {
    "node": ">=18.19"
  },
  "scripts": {
    "test": "node --test",
    "check": "node --check src/index.js && node --check src/resolver.js"
  },
  "keywords": [
    "resolve",
    "require.resolve",
    "module-resolution",
    "build-tool"
  ],
  "license": "MIT"
}

import { createRequire, isBuiltin as nodeIsBuiltin } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const PLACEHOLDER = '__resolve_from__.js';

function toParentFile(from) {
  const candidate =
    typeof from === 'string' && from.startsWith('file:')
      ? fileURLToPath(from)
      : path.resolve(from);

  if (path.extname(candidate) !== '') {
    return candidate;
  }
  return path.join(candidate, PLACEHOLDER);
}

function classify(specifier) {
  const builtin = nodeIsBuiltin(specifier) || specifier.startsWith('node:');
  const relative =
    specifier.startsWith('./') ||
    specifier.startsWith('../') ||
    specifier.startsWith('/');
  return { builtin, relative, bare: !builtin && !relative };
}

/**
 * Resolve a module specifier using Node's own CJS resolution algorithm,
 * anchored at `options.from`.
 *
 * @param {string} specifier
 * @param {{ from?: string }} [options]
 * @returns {{
 *   specifier: string,
 *   resolved: string,
 *   url: string,
 *   path: string | null,
 *   isBuiltin: boolean,
 *   isRelative: boolean,
 *   isBare: boolean,
 * }}
 */
export function resolve(specifier, options = {}) {
  if (typeof specifier !== 'string' || specifier.length === 0) {
    throw new TypeError('specifier must be a non-empty string');
  }

  const from = options.from ?? process.cwd();
  const { builtin, relative, bare } = classify(specifier);

  if (builtin) {
    return {
      specifier,
      resolved: specifier.startsWith('node:') ? specifier : `node:${specifier}`,
      url: specifier.startsWith('node:') ? specifier : `node:${specifier}`,
      path: null,
      isBuiltin: true,
      isRelative: false,
      isBare: false,
    };
  }

  const parent = toParentFile(from);
  const require = createRequire(pathToFileURL(parent));

  let resolved;
  try {
    resolved = require.resolve(specifier);
  } catch (err) {
    if (err && err.code === 'MODULE_NOT_FOUND') {
      throw new Error(
        `Cannot resolve "${specifier}" from "${parent}"`,
        { cause: err },
      );
    }
    throw err;
  }

  return {
    specifier,
    resolved,
    url: /^[a-z]+:/.test(resolved) ? resolved : pathToFileURL(resolved).href,
    path: resolved,
    isBuiltin: false,
    isRelative: relative,
    isBare: bare,
  };
}

/**
 * Resolve several specifiers from the same anchor. Unresolvable specifiers are
 * reported per-entry instead of aborting the whole batch.
 *
 * @param {string[]} specifiers
 * @param {{ from?: string }} [options]
 */
export function resolveAll(specifiers, options = {}) {
  return specifiers.map((specifier) => {
    try {
      return { specifier, ok: true, result: resolve(specifier, options) };
    } catch (error) {
      return { specifier, ok: false, error };
    }
  });
}

/**
 * Create a resolver bound to a fixed anchor.
 *
 * @param {{ from?: string }} [options]
 */
export function createResolver(options = {}) {
  const from = options.from ?? process.cwd();
  return {
    from,
    resolve: (specifier) => resolve(specifier, { from }),
    resolveAll: (specifiers) => resolveAll(specifiers, { from }),
  };
}

import assert from 'node:assert/strict';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

import { createResolver, resolve, resolveAll } from '../src/index.js';

const dirname = path.dirname(fileURLToPath(import.meta.url));
const fixtures = path.join(dirname, 'fixtures');
const consumer = path.join(fixtures, 'consumer.js');

test('resolves builtin modules with and without the node: prefix', () => {
  const plain = resolve('path');
  assert.equal(plain.isBuiltin, true);
  assert.equal(plain.resolved, 'node:path');
  assert.equal(plain.path, null);

  const prefixed = resolve('node:fs');
  assert.equal(prefixed.isBuiltin, true);
  assert.equal(prefixed.resolved, 'node:fs');
});

test('resolves relative specifiers from the anchor file', () => {
  const result = resolve('./lib.js', { from: consumer });
  assert.equal(result.path, path.join(fixtures, 'lib.js'));
  assert.equal(result.url, new URL('./lib.js', `file://${consumer}`).href);
  assert.equal(result.isRelative, true);
  assert.equal(result.isBare, false);
});

test('resolves bare specifiers through node_modules', () => {
  const result = resolve('fake-pkg', { from: consumer });
  assert.equal(result.path, path.join(fixtures, 'node_modules', 'fake-pkg', 'index.js'));
  assert.equal(result.isBare, true);
});

test('honors package exports subpaths', () => {
  const result = resolve('fake-pkg/sub', { from: consumer });
  assert.equal(
    result.path,
    path.join(fixtures, 'node_modules', 'fake-pkg', 'sub.js'),
  );
});

test('reports unresolvable specifiers with a helpful message', () => {
  assert.throws(
    () => resolve('does-not-exist-xyz', { from: consumer }),
    /Cannot resolve "does-not-exist-xyz"/,
  );
});

test('resolveAll collects successes and failures', () => {
  const results = resolveAll(['node:path', './lib.js', 'nope-xyz'], {
    from: consumer,
  });

  assert.deepEqual(
    results.map((r) => r.ok),
    [true, true, false],
  );
  assert.equal(results[0].result.resolved, 'node:path');
  assert.equal(results[1].result.path, path.join(fixtures, 'lib.js'));
  assert.ok(results[2].error instanceof Error);
});

test('createResolver binds the anchor', () => {
  const resolver = createResolver({ from: fixtures });
  assert.equal(resolver.from, fixtures);
  assert.equal(
    resolver.resolve('./lib.js').path,
    path.join(fixtures, 'lib.js'),
  );
});

